const tabId = 1148881640;

const info = await browserjs(tabId, () => {
  const covered = document.querySelector('button[aria-label*="Filters"]');
  if (!covered) return { noCovered: true };
  const rect = covered.getBoundingClientRect();
  const point = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
  const topElem = document.elementFromPoint(point.x, point.y);
  return {
    rect,
    point,
    topElem: topElem ? {
      tag: topElem.tagName,
      className: topElem.className,
      id: topElem.id,
      text: topElem.textContent?.slice(0, 150),
      html: topElem.outerHTML?.slice(0, 300)
    } : null
  };
});
console.log("Covering element info:", JSON.stringify(info, null, 2));

