const tabId = 1148881640;

const listingDetails = await browserjs(tabId, () => {
  // Extract all text, headings, amenities
  const h1 = document.querySelector('h1')?.textContent?.trim();
  const location = document.querySelector('h2, [data-section-id="OVERVIEW_DEFAULT"]')?.textContent?.trim();

  // Price breakdown
  const priceElements = Array.from(document.querySelectorAll('[data-testid*="price"], span, div'))
    .map(e => e.textContent?.trim())
    .filter(t => t && t.includes('$') && (t.includes('night') || t.includes('total') || t.includes('for 3 nights')));

  // Check guest info & dates on reservation widget
  const dates = document.querySelector('[data-testid*="change-dates"]')?.textContent?.trim();
  const guests = document.querySelector('[data-testid*="guest-picker"]')?.textContent?.trim();

  return {
    h1,
    dates,
    guests,
    priceElements: priceElements.slice(0, 10),
    url: window.location.href
  };
});
console.log("Listing overview:", listingDetails);

// Let's also check amenities on this page
// Many listings have a "Show all X amenities" button
const amenitiesCheck = await browserjs(tabId, () => {
  const amenityItems = Array.from(document.querySelectorAll('[data-section-id="AMENITIES_DEFAULT"] li, [data-section-id="AMENITIES_DEFAULT"] div'))
    .map(e => e.textContent?.trim())
    .filter(Boolean);

  const showAllAmenitiesBtn = Array.from(document.querySelectorAll('button')).find(b => b.textContent?.includes('amenities'));

  return {
    amenityItems: amenityItems.slice(0, 20),
    hasShowAllBtn: !!showAllAmenitiesBtn,
    showAllBtnText: showAllAmenitiesBtn?.textContent?.trim()
  };
});
console.log("Amenities check:", amenitiesCheck);

