const tabId = 1148881640;

const coveringInfo = await browserjs(tabId, () => {
  const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent?.includes('amenities'));
  if (!btn) return "Button not found";
  btn.scrollIntoView({ block: 'center', inline: 'center' });
  const rect = btn.getBoundingClientRect();
  const point = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
  const topElem = document.elementFromPoint(point.x, point.y);
  return {
    rect,
    point,
    topElem: topElem ? {
      tag: topElem.tagName,
      className: topElem.className,
      text: topElem.textContent?.slice(0, 100)
    } : null
  };
});
console.log("Covering info after scroll:", coveringInfo);

