const tabId = 1148881640;

const testFetch = await browserjs(tabId, async () => {
  const roomIds = [
    "1537379362009278442", // Apartment in Cleveland
    "994249795599984702",  // Home in Cleveland - Historic duplex loft
    "1749400564101812159", // Hotel in Lyndhurst
    "711778200588568147"   // Home in South Euclid
  ];

  const results = {};
  for (const id of roomIds) {
    try {
      const res = await fetch(`https://www.airbnb.com/rooms/${id}?adults=2&children=2&pets=1&check_in=2026-09-19&check_out=2026-09-22`);
      const html = await res.text();
      results[id] = {
        title: html.match(/<title>([^<]+)<\/title>/)?.[1],
        hasGym: /gym|fitness|exercise/i.test(html),
        hasWasher: /washer/i.test(html),
        hasParking: /free parking|parking/i.test(html),
        hasPet: /pet/i.test(html),
        gymMatches: html.match(/[^.>\n]*\b(gym|fitness)\b[^.<\n]*/gi)?.slice(0, 3)
      };
    } catch (e) {
      results[id] = { error: e.message };
    }
  }
  return results;
});

console.log("Fetch results:", JSON.stringify(testFetch, null, 2));

