const tabId = 1148881640;

const gymDetails = await browserjs(tabId, async () => {
  const ids = ["1537379362009278442", "994249795599984702", "1279101380644230922"];
  const res = {};
  for (const id of ids) {
    const r = await fetch(`https://www.airbnb.com/rooms/${id}`);
    const html = await r.text();
    // find all occurrences of gym, fitness, exercise
    const matches = [];
    const re = /([^<>{}]*(?:gym|fitness|exercise)[^<>{}]*)/gi;
    let m;
    while ((m = re.exec(html)) !== null) {
      if (!m[1].includes('function') && !m[1].includes('class') && m[1].length < 150) {
        matches.push(m[1].trim());
      }
    }
    res[id] = matches;
  }
  return res;
});

console.log("Gym matches in Cleveland listings:", JSON.stringify(gymDetails, null, 2));

