const tabId = 1148881640;

const amenitiesFull = await browserjs(tabId, () => {
  // Let's find the script tags with json data or amenity sections
  const scripts = Array.from(document.querySelectorAll('script[type="application/json"], script[id*="data"]'));
  let allAmenities = [];

  for (const s of scripts) {
    try {
      const json = JSON.parse(s.textContent);
      const str = JSON.stringify(json);
      if (str.includes('seeAllAmenitiesGroups')) {
        // extract seeAllAmenitiesGroups
        const matches = str.match(/"title":"([^"]+)","icon"/g);
        if (matches) {
          allAmenities = matches.map(m => m.replace('"title":"', '').replace('","icon"', ''));
        }
      }
    } catch (e) {}
  }

  // Also check direct text
  const bodyText = document.body.innerText;

  return {
    allAmenities,
    hasWasher: /washer|laundry/i.test(bodyText),
    hasGym: /gym|fitness/i.test(bodyText),
    hasParking: /free parking|parking/i.test(bodyText),
    hasPet: /pet/i.test(bodyText)
  };
});
console.log("Full amenities check:", amenitiesFull);

